using System;
using System.IO;
using System.Text.RegularExpressions;

string jilPath = Environment.GetEnvironmentVariable("JilPath") ?? "job.jil";

if (!File.Exists(jilPath))
{
    Console.WriteLine($"Error: File '{jilPath}' not found.");
    return;
}

Regex pattern = new Regex(@"^\s*command:\s*""?(?<cmd>[^""\r\n]+)""?\s*$", RegexOptions.IgnoreCase);
string commandPath = string.Empty;

foreach (string line in File.ReadLines(jilPath))
{
    Match match = pattern.Match(line);
    if (match.Success)
    {
        commandPath = match.Groups["cmd"].Value.Trim().Trim('"').Replace('\\', '/');
        break;
    }
}

if (!string.IsNullOrEmpty(commandPath))
{
    Console.Write(commandPath);
}
else
{
    Console.WriteLine("Error: 'command:' definition not found in JIL file.");
}


using System;
using System.IO;
using System.Text.RegularExpressions;

string targetPath = Environment.GetEnvironmentVariable("FilePath") ?? "setup.bat";

if (!File.Exists(targetPath))
{
    Console.WriteLine($"Error: File '{targetPath}' not found.");
    return;
}

Regex pattern = new Regex(@"^\s*SET\s+""?\s*LOG_FILE\s*=\s*""?(?<val>.*?)""?\s*$", RegexOptions.IgnoreCase);
string logFile = string.Empty;

foreach (string line in File.ReadLines(targetPath))
{
    Match match = pattern.Match(line);
    if (match.Success)
    {
        logFile = match.Groups["val"].Value.Trim().Trim('"').Replace('\\', '/');
        break;
    }
}

if (!string.IsNullOrEmpty(logFile))
{
    Console.Write(logFile);
}
else
{
    Console.WriteLine("Error: 'SET LOG_FILE' line not found in file.");
}


using System;
using System.IO;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Encodings.Web;

string batPath = Environment.GetEnvironmentVariable("FilePath");
string rawLogPath = Environment.GetEnvironmentVariable("LOGFILE_RESULTS");

if (string.IsNullOrWhiteSpace(rawLogPath))
{
    Console.WriteLine("Error: 'LOGFILE_RESULTS' is empty.");
    return;
}

rawLogPath = rawLogPath.Replace('\\', Path.DirectorySeparatorChar);

string resolvedPath = Path.GetFullPath(rawLogPath);

if (!File.Exists(resolvedPath) && !string.IsNullOrEmpty(batPath))
{
    string batDir = Path.GetDirectoryName(batPath) ?? ".";
    resolvedPath = Path.GetFullPath(Path.Combine(batDir, rawLogPath));
}

if (!File.Exists(resolvedPath))
{
    Console.WriteLine($"Error: Log file not found at '{resolvedPath}'");
    return;
}

// Normalize CRLF line breaks and replace backslashes to clean up extra escaping
string content = File.ReadAllText(resolvedPath)
    .Replace("\r\n", "\n")
    .Replace("\r", "")
    .Replace('\\', '/');

var jsonNode = new JsonObject
{
    ["content"] = content,
    ["timestamp"] = DateTime.UtcNow.ToString("o"),
    ["status"] = "Success"
};

// Prevent escaping single quotes to \u0027
var options = new JsonSerializerOptions
{
    WriteIndented = false,
    Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
};

string jsonString = jsonNode.ToJsonString(options);
Console.WriteLine(jsonString);
